<template><view class="screen"><view class="heading">个人设置</view><view v-if="error" class="error">{{error}}</view><view class="card"><view class="label">个人简介</view><textarea v-model="bio" maxlength="200" placeholder="介绍一下自己"/><input v-model="province" placeholder="所在省份"/><input v-model="city" placeholder="所在城市"/><picker :range="['未设置','男','女']" @change="gender=Number($event.detail.value)"><view class="item">性别：{{['未设置','男','女'][gender]}}</view></picker><button :disabled="busy" @click="save">保存资料</button></view><view class="card"><view class="title">手机号</view><view class="muted">{{account.user?.profile?.mobile?'已绑定 '+mask(account.user.profile.mobile):'尚未绑定'}}</view><button @click="auth(account.user?.has_mobile?'unbind':'bind')">{{account.user?.has_mobile?'验证短信并解绑':'绑定手机号'}}</button></view><view class="card"><view class="title">修改密码</view><input v-model="oldPw" password placeholder="原密码"/><input v-model="newPw" password placeholder="新密码（至少8位）"/><button :disabled="busy" @click="changePassword">保存新密码</button></view><view class="card"><view class="item" @click="clearCache">清理本地缓存 ›</view><view class="muted">不会清除云端收藏和论坛内容。</view><view class="item" @click="privacy=true">隐私说明 ›</view><view v-if="privacy" class="muted">登录凭证保存在本机；论坛会处理账号、发帖、短信验证和访问日志。AI 搜索会向管理员配置的 AI 服务发送问题及有权访问的检索片段。图片仅在你选择上传后提交到论坛。卸载 APP 可清除本机数据；账号数据处理请联系论坛管理员。</view></view><button @click="logout" class="danger">退出登录</button></view></template>
<script setup>
import { ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { post,requireLogin } from '../../api/index.js'
import { useAccount } from '../../store/account.js'
const account=useAccount(),bio=ref(''),province=ref(''),city=ref(''),gender=ref(0),oldPw=ref(''),newPw=ref(''),busy=ref(false),error=ref(''),privacy=ref(false)
function mask(s){return s.slice(0,3)+'****'+s.slice(-4)}
function auth(mode){uni.navigateTo({url:'/pages/auth/index?mode='+mode})}
async function save(){if(busy.value)return;busy.value=true;try{await post('user/settings.php',{bio:bio.value,resideprovince:province.value,residecity:city.value,gender:gender.value});await account.refresh();uni.showToast({title:'资料已保存'})}catch(e){error.value=e.message}finally{busy.value=false}}
async function changePassword(){if(busy.value)return;busy.value=true;try{await post('user/settings.php',{action:'password',old_password:oldPw.value,new_password:newPw.value});account.clear();oldPw.value='';newPw.value='';uni.redirectTo({url:'/pages/auth/index'})}catch(e){error.value=e.message}finally{busy.value=false}}
function clearCache(){uni.showModal({title:'清理缓存',content:'清除本地收藏与搜索历史？',success:r=>{if(r.confirm){uni.removeStorageSync('zo-favorites');uni.removeStorageSync('zo-search-history');uni.showToast({title:'缓存已清理'})}}})}
async function logout(){try{await account.logout();uni.reLaunch({url:'/pages/index/index'})}catch(e){error.value=e.message}}
onShow(async()=>{if(!requireLogin())return;try{await account.refresh();const p=account.user.profile||{};bio.value=p.bio||'';province.value=p.resideprovince||'';city.value=p.residecity||'';gender.value=Number(p.gender)||0}catch(e){error.value=e.message}})
</script>
<style scoped>.screen{padding:20px 16px 40px}.heading{font-size:30px;font-weight:800;margin:20px 4px}input,textarea{background:var(--bg);margin:14px 0}textarea{width:100%;height:90px;padding:12px;box-sizing:border-box;border-radius:12px}.item{padding:18px 0}.danger{background:#ff3b30}button{margin-top:16px}</style>
